@startuml
class Kinepolis {}
class Cinema {
  +town: string
}
class Theatre {
  +theatreNumber: int
}
class Movie {}
class MovieCopy {}
class Show {
  +startTime: datetime
}
class Reservation {
  +reservationTime: datetime
}
class Seat {
  +seatNumber: int
}
class CreditCard {}
class Ticket {
  +isAnonymous: boolean
}
class Offer {
  +expiryTime: datetime
}

Kinepolis "1" -- "*" Cinema : owns

Cinema "1" *-- "*" Theatre : has
Cinema "1" -- "*" MovieCopy : owns

Theatre "1" -- "*" Show : hosts
Show "*" -- "1" Movie : features
Show "1" -- "1" MovieCopy : uses

Show "1" -- "*" Reservation : has
Reservation "1" -- "1" Seat : reserves
Reservation "*" -- "1" CreditCard : paid with

Show "1" -- "*" Ticket : issues
Ticket "1" -- "1" Seat : assigns
Ticket "1" -- "1" Show : for

Show "1" -- "*" Offer : provides
Offer "1" -- "1" Reservation : for
@enduml

